<script setup>
import { onMounted, ref } from 'vue'
import { api, errorMessage } from '../api.js'
import { formatTime } from '../time.js'
import StatusBadge from '../components/StatusBadge.vue'
import PaginationBar from '../components/PaginationBar.vue'
const data = ref({ content: [], page: 0, totalPages: 0, totalElements: 0 }), busy = ref(false), error = ref('')
const editable = r => ['PENDING', 'RETRY'].includes(r.status)
async function load(page = data.value.page) { busy.value = true; error.value = ''; try { data.value = (await api.get('/reminders', { params: { page, size: 20 } })).data } catch (e) { error.value = errorMessage(e) } finally { busy.value = false } }
async function action(r, name) { if (!window.confirm(name === 'cancel' ? 'Cancel this reminder? A later edit cannot recall an email already being processed.' : 'Remove this reminder from your list? Its email history will be retained.')) return; busy.value = true; try { if (name === 'cancel') await api.post(`/reminders/${r.id}/cancel`); else await api.delete(`/reminders/${r.id}`); await load(name === 'delete' ? 0 : data.value.page) } catch (e) { error.value = errorMessage(e) } finally { busy.value = false } }
onMounted(() => load())
</script>
<template><div class="page-heading"><div><span class="eyebrow">ALL YOUR PLANS</span><h1>My reminders</h1><p>Upcoming moments, completed nudges, and everything in between.</p></div><RouterLink to="/reminders/new" class="button primary">+ Create reminder</RouterLink></div><p v-if="error" class="notice error" role="alert">{{ error }}</p><section class="panel"><div class="panel-heading"><div><h2>Reminder workspace</h2><p>{{ data.totalElements }} reminders · ordered by scheduled time</p></div><button class="button ghost small" :disabled="busy" @click="load()">{{ busy ? 'Loading…' : '↻ Refresh' }}</button></div><div v-if="!busy && !data.content.length" class="empty-state large"><span>◷</span><h3>Something worth remembering?</h3><p>Create your first reminder and let us keep an eye on the clock.</p><RouterLink to="/reminders/new" class="button primary">Create reminder</RouterLink></div><div v-else class="table-scroll"><table><thead><tr><th>Reminder / recipient</th><th>Scheduled for</th><th>Status</th><th>Attempts</th><th>Actions</th></tr></thead><tbody><tr v-for="r in data.content" :key="r.id"><td><strong>{{ r.title }}</strong><small>{{ r.recipientEmail }}</small></td><td>{{ formatTime(r.scheduledAt, r.timeZone) }}<small>{{ r.timeZone }}</small><small v-if="r.status === 'RETRY'">Next retry: {{ formatTime(r.nextAttemptAt, r.timeZone) }}</small></td><td><StatusBadge :status="r.status" /></td><td>{{ r.attemptCount }}<small>{{ r.retryCount }} retries</small></td><td><div class="row-actions"><RouterLink v-if="editable(r)" :to="`/reminders/${r.id}/edit`">Edit</RouterLink><RouterLink :to="`/history?reminderId=${r.id}`">History</RouterLink><button v-if="editable(r)" :disabled="busy" @click="action(r, 'cancel')">Cancel</button><button v-if="['SENT', 'FAILED', 'CANCELLED'].includes(r.status)" class="danger-text" :disabled="busy" @click="action(r, 'delete')">Delete</button></div></td></tr></tbody></table></div><PaginationBar :page="data.page" :total-pages="data.totalPages" :total-elements="data.totalElements" :busy="busy" @change="load" /></section><p class="fine-print">Processing reminders cannot be edited or recalled. Cancel a pending reminder before deleting it.</p></template>
